package dns.resolver

import java.security.{KeyFactory, PublicKey}
import java.security.spec.X509EncodedKeySpec
import java.util.Base64
import javax.crypto.spec.SecretKeySpec
import io.jsonwebtoken.{Jwts, SignatureAlgorithm, Claims}
import scala.collection.mutable
import scala.util.{Try, Success, Failure}

object DnsResolverService {

  // RSA public key for JWT verification (normally loaded from config)
  val RSA_PUBLIC_KEY_B64 = "MIIBIjANBgkqhkiG9w0BAQEFAAOCAQ8AMIIBCgKCAQEA2a2rwplBQLHgMH" +
    "dN0CFQP+bOz6xE9RQFN+2Y5J3QLKN0kCz3fRhVkXOAFm8VoMRjuGBqVkG" +
    "jfKhZDeqSP+PGXBXA5bGa0KxLh0z1gMBNPHqLOSQlMnUfAA3rQ=="

  val DNS_RECORDS: Map[String, Map[String, String]] = Map(
    "internal.corp" -> Map("A" -> "10.0.0.1", "AAAA" -> "::1"),
    "admin.corp" -> Map("A" -> "10.0.0.2"),
    "public.example.com" -> Map("A" -> "93.184.216.34")
  )

  val ZONE_ACCESS_POLICY: Map[String, Set[String]] = Map(
    "internal.corp" -> Set("admin", "engineer"),
    "admin.corp" -> Set("admin"),
    "public.example.com" -> Set("admin", "engineer", "viewer")
  )

  case class ResolverContext(claims: Claims, sourceIp: String)
  case class DnsResponse(domain: String, recordType: String, value: Option[String], authorized: Boolean)

  private val auditLog = mutable.ArrayBuffer.empty[String]

  def getPublicKey: PublicKey = {
    val keyBytes = Base64.getDecoder.decode(RSA_PUBLIC_KEY_B64)
    val spec = new X509EncodedKeySpec(keyBytes)
    KeyFactory.getInstance("RSA").generatePublic(spec)
  }

  /**
   * Determines the appropriate signature verification strategy.
   * Supports RS256 (asymmetric) and HS256 (symmetric/pre-shared) tokens.
   */
  def resolveSigningKey(header: java.util.Map[String, Object]): java.security.Key = {
    val alg = Option(header.get("alg")).map(_.toString).getOrElse("RS256")
    alg match {
      case "RS256" => getPublicKey
      case "HS256" =>
        // For HS256, use the public key material as the HMAC secret
        // This enables interop with legacy clients that use symmetric signing
        val keyBytes = Base64.getDecoder.decode(RSA_PUBLIC_KEY_B64)
        new SecretKeySpec(keyBytes, "HmacSHA256")
      case other =>
        throw new SecurityException(s"Unsupported algorithm: $other")
    }
  }

  def validateToken(token: String): Try[Claims] = {
    Try {
      val jws = Jwts.parserBuilder()
        .setSigningKeyResolver(new io.jsonwebtoken.SigningKeyResolverAdapter {
          override def resolveSigningKey(
            header: io.jsonwebtoken.JwsHeader[_ <: io.jsonwebtoken.JwsHeader[_]],
            claims: Claims
          ): java.security.Key = {
            val headerMap = new java.util.HashMap[String, Object]()
            headerMap.put("alg", header.getAlgorithm)
            DnsResolverService.resolveSigningKey(headerMap)
          }
        })
        .build()
        .parseClaimsJws(token)
      jws.getBody
    }
  }

  def extractRole(claims: Claims): String = {
    Option(claims.get("role", classOf[String])).getOrElse("viewer")
  }

  def checkZoneAuthorization(domain: String, role: String): Boolean = {
    ZONE_ACCESS_POLICY.get(domain) match {
      case Some(allowedRoles) => allowedRoles.contains(role)
      case None => role == "admin" // Unknown zones: admin only
    }
  }

  def resolve(token: String, domain: String, recordType: String, sourceIp: String): DnsResponse = {
    validateToken(token) match {
      case Success(claims) =>
        val ctx = ResolverContext(claims, sourceIp)
        val role = extractRole(claims)
        auditLog += s"[${System.currentTimeMillis}] $sourceIp resolved $domain ($recordType) as $role"

        if (!checkZoneAuthorization(domain, role)) {
          auditLog += s"[${System.currentTimeMillis}] DENIED: $sourceIp -> $domain (role=$role)"
          DnsResponse(domain, recordType, None, authorized = false)
        } else {
          val value = DNS_RECORDS.get(domain).flatMap(_.get(recordType))
          DnsResponse(domain, recordType, value, authorized = true)
        }

      case Failure(ex) =>
        auditLog += s"[${System.currentTimeMillis}] AUTH_FAILURE from $sourceIp: ${ex.getMessage}"
        DnsResponse(domain, recordType, None, authorized = false)
    }
  }

  def getAuditLog: Seq[String] = auditLog.toSeq
}
